recipes.code:
{
  "inputs": [
    {
      "id": "uploadcheck-api-key",
      "type": "promptString",
      "description": "Workspace API key from your UploadCheck setup email (get one at https://uploadcheck.app/checkout/)",
      "password": true
    }
  ],
  "servers": {
    "uploadcheck": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@drantoniou/uploadcheck-mcp@0.1.1"
      ],
      "env": {
        "UPLOADCHECK_API_BASE_URL": "https://api.uploadcheck.app",
        "UPLOADCHECK_API_KEY": "${input:uploadcheck-api-key}"
      }
    }
  }
}
